# hypothesis: Any is gradual, so an Any-typed value flows into an int parameter without error, while an object value needs isinstance narrowing before the same call is accepted.
from typing import Any, assert_type, cast, reveal_type


def takes_int(n: int) -> int:
    return n + 1


def from_any(v: Any) -> int:
    return takes_int(v)


def from_object(o: object) -> int:
    if isinstance(o, int):
        return takes_int(o)
    return -1


def relocated(seed: Any) -> list[int]:
    def inner() -> list[int]:
        out: list[int] = []
        out.append(takes_int(seed))
        return out

    return inner()


def cast_then_assert(raw: Any) -> int:
    n = cast(int, raw)
    assert_type(n, int)
    return n


x: Any = 41
assert_type(from_any(x), int)
reveal_type(x)
assert from_any(x) == 42
assert from_object(5) == 6
assert from_object('s') == -1
assert relocated(1) == [2]
assert cast_then_assert(9) == 9
